def generate_row(k, M):
    # R_k(i) = ((i-1+k) mod M) + 1 for 1-based index i
    row = []
    for i in range(1, M + 1):
        # i is 1-based index, so i-1 is 0-based index
        value = ((i - 1 + k) % M) + 1
        row.append(value)
    return row

M = 16
N = 16
rows = [generate_row(k, M) for k in range(N)]

def check_condition_ii(row1, row2):
    # Check if for any two distinct rows, there is a column c such that |T(r, c)-T(s, c)| >= 2
    for c in range(M):
        diff = abs(row1[c] - row2[c])
        if diff >= 2:
            return True
    return False

all_pairs_valid = True
for j in range(N):
    for k in range(j + 1, N):
        r_j = rows[j]
        r_k = rows[k]
        if not check_condition_ii(r_j, r_k):
            print(f"Failure found between rows {j} and {k}")
            print(f"Row {j}: {r_j}")
            print(f"Row {k}: {r_k}")
            all_pairs_valid = False
            break
    if not all_pairs_valid:
        break

if all_pairs_valid:
    print("Verification successful: The N=16 cyclic shift construction satisfies condition (ii) for all pairs.")
else:
    print("Verification failed.")
